def transform(grid):
    h,w=len(grid),len(grid[0])
    tile=[[0 if grid[r][c] else 1 for c in range(w)] for r in range(h)]
    out=[[0]*(3*w) for _ in range(3*h)]
    for r in range(h):
        for c in range(w):
            v=grid[r][c]
            if v:
                for tr in range(h):
                    for tc in range(w):
                        if tile[tr][tc]:
                            out[3*r+tr][3*c+tc]=v
    return out
